def rgb_to_hls(r, g, b):
    maxc = max(r, g, b)
    minc = min(r, g, b)
    sumc = (maxc+minc)
    rangec = (maxc-minc)
    l = sumc/2.0
    if minc == maxc:
        return 0.0, l, 0.0
    if l <= 0.5:
        s = rangec / sumc
    else:
        s = rangec / (2.0 - maxc - minc)
    rc = (maxc-r) / rangec
    gc = (maxc-g) / rangec
    bc = (maxc-b) / rangec
    if r == maxc:
        h = bc-gc
    elif g == maxc:
        h = 2.0+rc-bc
    else:
        h = 4.0+gc-rc
    h = (h/6.0) % 1.0
    return h, l, s

def midrange(data):
    if not data:
        raise StatisticsError("Data cannot be empty")
    return (min(data) + max(data)) / 2.0

def isleap(year):
    """Return True for leap years, False for non-leap years."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

import threading
import queue

class TextWrapper:
    def __init__(self, width=70, **kwargs):
        self.width = width
        self.kwargs = kwargs
        self.queue = queue.Queue()

    def _wrap(self, text):
        w = TextWrapper(self.width, **self.kwargs)
        return w.wrap(text)

    def wrap(self, text):
        self.queue.put(text)
        return self._wrap(self.queue.get())

def safe_wrap(text, width=70, **kwargs):
    wrapper = TextWrapper(width, **kwargs)
    return wrapper.wrap(text)
